      "external_id": "rss:neurips-blog:a9465d9669b5be0e83cc3de7",
      "type": "news",
      "source": "NeurIPS Blog",
      "title": "Announcing the NeurIPS 2026 Journal Track",
      "summary": "Announcing the NeurIPS 2026 Journal Track The NeurIPS Journal Track aims to strengthen the bridge between machine learning and statistics communities and enable the dissemination of scientific knowledge. Journals such as Journal of Machine Learning Research (JMLR), Transactions on Machine Learning Research (TMLR), and Annals of Statistics (AoS) accept rigorously reviewed papers on a rolling […]",
      "summary_ko": "NeurIPS Blog가 공개한 소식으로, 학습 방법·이론 분야의 일반 머신러닝 변화에 초점을 둡니다. 새로운 방법과 실험 결과, 실제 활용 가능성을 중심으로 핵심 내용을 살펴봅니다.",
      "motivation_ko": "새로운 데이터 분포에서도 성능이 유지되고 학습 결과를 재현할 수 있는 일반화가 핵심 과제입니다.",
      "contribution_ko": "실험과 분석을 통해 기존 접근법의 동작 특성을 설명하고 개선 가능성을 뒷받침하는 근거를 제공합니다. 핵심 검증 대상은 일반 머신러닝의 성능과 실제 적용 가능성입니다.",
      "url": "https://blog.neurips.cc/2026/10/15/announcing-the-neurips-2026-journal-track/",
      "published_at": "2026-10-15T21:59:42+00:00",
